update public.tarefa_cards t
set descricao = $juff$<p><strong>RUNNING</strong> <a href="https://br.freepik.com/vetores-gratis/ilustracao-de-execucao-de-mulher-geometrica-azul_13381520.htm#query=TRIATHLON&amp;position=18&amp;from_view=search&amp;track=sph" target="_blank" rel="noopener">https://br.freepik.com/vetores-gratis/ilustracao-de-execucao-de-mulher-geometrica-azul_13381520.htm#query=TRIATHLON&amp;position=18&amp;from_view=search&amp;track=sph</a></p><p><a href="https://br.freepik.com/vetores-gratis/design-plano-de-silhueta-abstrata-corredor_4927829.htm#query=TRIATHLON&amp;position=20&amp;from_view=search&amp;track=sph" target="_blank" rel="noopener">https://br.freepik.com/vetores-gratis/design-plano-de-silhueta-abstrata-corredor_4927829.htm#query=TRIATHLON&amp;position=20&amp;from_view=search&amp;track=sph</a></p><p><strong>BIKE</strong> <a href="https://br.freepik.com/vetores-gratis/fundo-do-sol-com-uma-silhueta-ciclista_886427.htm#query=BIKE%20SILK&amp;position=2&amp;from_view=search&amp;track=ais" target="_blank" rel="noopener">https://br.freepik.com/vetores-gratis/fundo-do-sol-com-uma-silhueta-ciclista_886427.htm#query=BIKE%20SILK&amp;position=2&amp;from_view=search&amp;track=ais</a></p>$juff$
