update public.tarefa_cards t
set descricao = coalesce(t.descricao, '') || $juff$<hr><p>No banner régua, inserimos os icones em svg, eles estao muito pequenos. Além disso essa regua nao acompanha o layout do grid do site, ela precisa estar alinhada com a borda master do grid, e também os espaçamentos precisam ser uniformes. os ícones nao estao espaçados isometricamente, e precisam estar.</p><hr><p>Tirar a palavra “ver” de todos os itens responsivos do menu, está estranho.</p><hr><p>voltar em tres colunas como era anteriormente para as fotos ficarem um pouco maior. pois 4 colunas ficou pequeno.</p><hr><p>A FOTO DO PRODUTO precisa ser a mesma foto da cor do filtro ( variação cor) na hora que a pessoa clicar em cor. E se n ao tiver em estoque nao pode aparecer o produto.</p><hr><p>CARACTERISTICAS ESCOLHIDAS PARA APARECER NO CANTINHO DAS FOTOS</p><p>proteção UV</p><p>100% poliamida</p><p>Tecnologia antiodor</p><p>Secagem rápida</p><hr>$juff$
from public.tarefa_quadros q
where q.id = t.quadro_id
  and q.nome = 'Juff Store'
  and t.titulo = 'MAMD site Juff Store'
  and t.arquivado = false
  and position($juff$<p>No banner régua, inserimos os icones em svg, eles estao muito pequenos. Além disso essa$juff$ in coalesce(t.descricao, '')) = 0;

insert into public.tarefa_cards (quadro_id, coluna_id, titulo, descricao, posicao, criado_por, responsavel_id)
select q.id, c.id, 'DISCLAIMER', $juff$<p>FAZER UMA FRASE DE DISCLAIMER ISENTANDO SOBRE DIREITOS DE PROPRIEDADE INTELECTUAL DOS LOGOS DE TERCEIROS, VERIFICAR SOBRE ISSO.</p><p>✅ <strong>Comentário jurídico sobre a situação</strong></p><p>Quando um cliente envia à Juff o logo de terceiros — como de patrocinadores, marcas ou parceiros — para aplicação nas camisetas, estamos lidando com <strong>direitos de uso de marcas registradas</strong>, ou seja, <strong>propriedade intelectual de titularidade de terceiros</strong>.</p><p>Mesmo que o cliente tenha uma relação com o patrocinador, <strong>o fato de ele fornecer a arte não implica automaticamente que a Juff tenha autorização legal para usá-la</strong>. O uso indevido de marcas registradas pode gerar <strong>responsabilidade civil e, em casos mais graves, até sanções previstas na Lei de Propriedade Industrial (Lei nº 9.279/96)</strong>, além de consequências no âmbito do direito autoral (Lei nº 9.610/98), se envolver elementos artísticos protegidos.</p><p>Por isso, é <strong>essencial proteger a Juff com um termo de isenção de responsabilidade</strong> onde o cliente declara expressamente que:</p><ul><li><p>Tem autorização para uso dos logos fornecidos;</p></li><li><p>Assume total responsabilidade por qualquer questionamento legal futuro.</p></li></ul><p>Essa declaração deve constar formalmente em qualquer contrato, proposta ou aceite comercial. Inclusive, recomendo ter um <strong>modelo-padrão de termo de responsabilidade anexo aos pedidos personalizados com logos de terceiros</strong>.</p><hr><h4>✅ <strong>Frase de disclaimer (curta e jurídica)</strong></h4><p><em>“Ao fornecer logos ou artes de terceiros, o cliente declara possuir autorização legal para seu uso e isenta a Juff de qualquer responsabilidade quanto a direitos autorais e marcas registradas.”</em></p><hr><h4>✅ <strong>Explicação complementar que pode acompanhar (em linguagem simples e clara no corpo do material ou site)</strong></h4><p><em>Importante: a Juff apenas executa a personalização conforme os arquivos recebidos. Ao enviar logos ou artes de terceiros (como patrocinadores ou marcas), você nos garante que tem permissão para utilizar essas imagens. Caso haja qualquer reivindicação por parte dos titulares dessas marcas, a responsabilidade será exclusivamente do cliente.</em></p>$juff$,
       coalesce((select max(x.posicao) + 1 from public.tarefa_cards x where x.coluna_id = c.id), 0),
       p.id, p.id
from public.tarefa_quadros q
join public.tarefa_colunas c on c.quadro_id = q.id and c.nome = 'Planejamento' and c.arquivado = false
join public.profiles p on p.email = 'marketing@juff.com.br'
where q.nome = 'Juff Custom' and q.arquivado = false
  and not exists (
    select 1 from public.tarefa_cards y
    where y.quadro_id = q.id and y.titulo = 'DISCLAIMER'
  );

insert into public.tarefa_cards (quadro_id, coluna_id, titulo, descricao, posicao, criado_por, responsavel_id)
